'use client';

import { useEffect, useRef, type CSSProperties } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import { DemoBand } from './_parts/demo-band';
import { DEFAULT_HUE, useHueCycle } from './_parts/hue';
import { runWhileShowing } from './_parts/loops';
import { softFieldOf } from './_parts/soft-field';

type Field = {
  id: string;
  style: CSSProperties;
  /** Milliseconds for one round of the path. The three differ, so the fields never drift in step. */
  periodMs: number;
  path: Keyframe[];
};

const FIELD_SHAPE = 'closest-side';

function restOf(
  left: string,
  top: string,
  width: string,
  strength: number
): CSSProperties {
  const backgroundImage = softFieldOf(FIELD_SHAPE, strength);
  return { left, top, width, backgroundImage };
}

/** Each leg eases in and out, so a field turns at a waypoint without a corner in its path. */
function legTo(transform: string): Keyframe {
  return { transform, easing: 'ease-in-out' };
}

const FIELDS: Field[] = [
  {
    id: 'near',
    style: restOf('26%', '34%', 'min(64%, 46rem)', 24),
    periodMs: 47000,
    path: [
      legTo('translate(0%, 0%) scale(1)'),
      legTo('translate(14%, 8%) scale(1.08)'),
      legTo('translate(5%, -10%) scale(0.94)'),
      legTo('translate(0%, 0%) scale(1)'),
    ],
  },
  {
    id: 'far',
    style: restOf('74%', '70%', 'min(56%, 40rem)', 17),
    periodMs: 61000,
    path: [
      legTo('translate(0%, 0%) scale(1)'),
      legTo('translate(-12%, -9%) scale(0.93)'),
      legTo('translate(-4%, 10%) scale(1.07)'),
      legTo('translate(0%, 0%) scale(1)'),
    ],
  },
  {
    id: 'high',
    style: restOf('54%', '16%', 'min(42%, 30rem)', 13),
    periodMs: 79000,
    path: [
      legTo('translate(0%, 0%) scale(1)'),
      legTo('translate(10%, 12%) scale(1.1)'),
      legTo('translate(-13%, 5%) scale(0.96)'),
      legTo('translate(0%, 0%) scale(1)'),
    ],
  },
];

function driftsOf(host: HTMLElement, fields: Field[]) {
  const drifts: Animation[] = [];
  fields.forEach((field, index) => {
    const element = host.children.item(index);
    if (!element) {
      return;
    }
    const drift = element.animate(field.path, {
      duration: field.periodMs,
      iterations: Infinity,
    });
    drifts.push(drift);
  });
  return drifts;
}

export type DriftingFieldsProps = {
  className?: string;
  /** Any colour token, such as `var(--primary)` or `var(--series-2)`. The fields wear it at different strengths. */
  hue?: string;
  /** How many fields drift. */
  count?: 1 | 2 | 3;
};

/**
 * Up to three soft fields of one hue that drift behind content. Each is a radial gradient that
 * fades to nothing, moved by a transform alone: no filter, and nothing repainted while they drift.
 * It fills its parent, which must be positioned. Under reduced motion the fields rest in place.
 */
export function DriftingFields({
  className,
  hue = DEFAULT_HUE,
  count = 3,
}: DriftingFieldsProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const fields = FIELDS.slice(0, count);

  useEffect(() => {
    const host = hostRef.current;
    if (!host || shouldReduceMotion) {
      return;
    }
    const drifting = FIELDS.slice(0, count);
    const drifts = driftsOf(host, drifting);
    return runWhileShowing(host, drifts);
  }, [count, shouldReduceMotion]);

  return (
    <div
      ref={hostRef}
      aria-hidden='true'
      style={{ color: hue }}
      className={cn(
        'pointer-events-none absolute inset-0 overflow-hidden transition-colors duration-500',
        className
      )}
    >
      {fields.map((field) => (
        <div
          key={field.id}
          style={field.style}
          className='absolute aspect-5/4 -translate-1/2'
        />
      ))}
    </div>
  );
}

export default function Background01() {
  const { hue, nextHue } = useHueCycle();

  return (
    <DemoBand
      title='Three fields of one hue, drifting'
      background={<DriftingFields hue={hue} />}
    >
      <Button onClick={nextHue}>Change hue</Button>
    </DemoBand>
  );
}

import { useId, type ReactNode, type Ref } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

type BandAlign = 'center' | 'end';

const ALIGNMENTS: Record<BandAlign, string> = {
  center: 'justify-center',
  end: 'justify-end pb-10',
};

type DemoBandProps = {
  ref?: Ref<HTMLElement>;
  title: string;
  /** The background under test. It fills the band, behind the headline and the actions. */
  background: ReactNode;
  /** `end` sets the headline at the foot of the band and leaves its middle to the background. */
  align?: BandAlign;
  children: ReactNode;
};

/**
 * The band every background is shown in: the page colour, a headline in the foreground colour and
 * the actions laid straight over the background, to prove that text stays readable above it.
 */
export function DemoBand({
  ref,
  title,
  background,
  align = 'center',
  children,
}: DemoBandProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={cn(
        'bg-background @container relative isolate flex h-90 w-full flex-col items-center overflow-hidden rounded-xl',
        ALIGNMENTS[align]
      )}
    >
      {background}
      <div className='relative flex max-w-lg flex-col items-center gap-5 px-6 text-center'>
        <h3
          id={titleId}
          className='text-2xl font-semibold text-balance @lg:text-3xl'
        >
          {title}
        </h3>
        <div className='flex flex-wrap items-center justify-center gap-2'>
          {children}
        </div>
      </div>
    </section>
  );
}

'use client';

import { useState } from 'react';

/** A background wears one hue: the brand unless it is told otherwise. */
export const DEFAULT_HUE = 'var(--primary)';

/** The brand first, then the series hues that differ from it. */
const DEMO_HUES = [
  DEFAULT_HUE,
  'var(--series-2)',
  'var(--series-3)',
  'var(--series-4)',
  'var(--series-5)',
];

/** The hue of a demo, and the step to the next one, to show a background in each hue it accepts. */
export function useHueCycle() {
  const [index, setIndex] = useState(0);
  const hue = DEMO_HUES[index] ?? DEFAULT_HUE;

  function nextHue() {
    setIndex((current) => {
      const next = current + 1;
      return next % DEMO_HUES.length;
    });
  }

  return { hue, nextHue };
}

import { watchShowing } from './showing';

function hold(animations: Animation[]) {
  for (const animation of animations) {
    animation.pause();
  }
}

function resume(animations: Animation[]) {
  for (const animation of animations) {
    animation.play();
  }
}

function cancel(animations: Animation[]) {
  for (const animation of animations) {
    animation.cancel();
  }
}

/**
 * Lands every transition still running under `host` at its end value. A transition asks for frames
 * until it ends, on screen or not, and a host that stops showing must ask for none.
 */
export function landTransitions(host: Element) {
  const animations = host.getAnimations({ subtree: true });
  for (const animation of animations) {
    const isTransition = animation instanceof CSSTransition;
    if (isTransition) {
      animation.finish();
    }
  }
}

/**
 * Endless animations that run only while their host shows. Off screen and in a hidden tab they are
 * paused: they keep their place and ask for no frame. They start paused, and `onShowing` is told
 * each time the host starts or stops showing. The function returned removes them.
 */
export function runWhileShowing(
  host: Element,
  animations: Animation[],
  onShowing?: (isShowing: boolean) => void
) {
  hold(animations);
  const stopWatching = watchShowing(host, (isShowing) => {
    onShowing?.(isShowing);
    if (isShowing) {
      resume(animations);
      return;
    }
    hold(animations);
  });
  return () => {
    stopWatching();
    cancel(animations);
  };
}

/**
 * A background sits behind content for as long as the page is open, so everything it runs hangs on
 * this answer: its box touches the screen and the tab is the one looked at. `onChange` is called
 * each time the answer changes, starting from "not showing". The function returned ends the watch.
 */
export function watchShowing(
  element: Element,
  onChange: (isShowing: boolean) => void
) {
  let isOnScreen = false;
  let wasShowing = false;

  function report() {
    const isTabShown = document.visibilityState === 'visible';
    const isShowing = isOnScreen && isTabShown;
    if (isShowing === wasShowing) {
      return;
    }
    wasShowing = isShowing;
    onChange(isShowing);
  }

  function onCrossing(entries: IntersectionObserverEntry[]) {
    const latest = entries.at(-1);
    if (!latest) {
      return;
    }
    isOnScreen = latest.isIntersecting;
    report();
  }

  const observer = new IntersectionObserver(onCrossing);
  observer.observe(element);
  document.addEventListener('visibilitychange', report);

  return () => {
    observer.disconnect();
    document.removeEventListener('visibilitychange', report);
  };
}

/** A fall from full to nothing with no visible edge: the share of the strength left at each quarter of the way out. */
const FALLOFF = [1, 0.85, 0.5, 0.15, 0];

const QUARTER = 25;

function stopOf(strength: number, share: number, index: number) {
  const exact = strength * share;
  const scaled = Math.round(exact * 100);
  const percent = scaled / 100;
  const position = index * QUARTER;
  return `color-mix(in oklab, currentColor ${percent}%, transparent) ${position}%`;
}

/**
 * A radial gradient of the current colour that fades to nothing with a soft edge, as a blur would
 * draw it, without a filter. `shape` is the shape and the place of the gradient, `strength` the
 * per cent of the colour at its heart.
 */
export function softFieldOf(shape: string, strength: number) {
  const stops = FALLOFF.map((share, index) => stopOf(strength, share, index));
  const ramp = stops.join(', ');
  return `radial-gradient(${shape}, ${ramp})`;
}
